#include <aibs/render.hpp>
#include "../apps/memory_content_budget.hpp"
#include <aibs/textured_scene.hpp>
#include <aibs/lighting.hpp>
#include <aibs/character_assets.hpp>
#include <aibs/character_scene.hpp>
#include <aibs/engine.hpp>
#include <array>
#include <cmath>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <limits>
#include <stdexcept>
using namespace aibs;
namespace {
std::size_t checks=0;
void need(bool b,const char* why){++checks;if(!b)throw std::runtime_error(why);}
void quad(SceneMesh& m,Vec3 a,Vec3 b,Vec3 c,Vec3 d,Vec3 n,Vec3 color){for(const auto p:{a,b,c,a,c,d})m.vertices.push_back({p,n,color,0});}
SceneMesh base(bool changed=false){SceneMesh m;quad(m,{-4,-.1f,-2},{-4,-.1f,6},{4,-.1f,6},{4,-.1f,-2},{0,1,0},changed?Vec3{.25f,.08f,.03f}:Vec3{.04f,.12f,.08f});quad(m,{-4,0,3},{-4,4,3},{4,4,3},{4,0,3},{0,0,-1},{.03f,.05f,.08f});return m;}
TexturedScene textured(){TexturedScene t;t.vertices={{{-1.5f,.1f,.8f},{0,0,-1},0,0},{{-.2f,.1f,.8f},{0,0,-1},1,0},{{-.8f,1.5f,.8f},{0,0,-1},.5f,1}};t.images={{ImageSemantic::srgb_color,{{2,2,{255,20,10,255,10,255,20,255,20,10,255,255,255,255,255,255}}}}};generate_image_mips(t.images.front());t.draws={{0,3,0,{1,1,1},.2f}};validate_textured_scene(t);return t;}
SceneLighting lighting(){SceneLighting l;l.enabled=true;l.ambient={.2f,.2f,.2f};const auto length=std::sqrt(1.5f);l.directional=DirectionalLight{{.5f/length,-1.f/length,.5f/length},{1,.8f,.6f},1};l.shadow.enabled=true;l.shadow.resolution=1024;l.shadow.center={0,1,0};l.shadow.half_extent=8;l.shadow.near_plane=.1f;l.shadow.far_plane=32;validate_scene_lighting(l);return l;}
CharacterAsset character(){CharacterAsset a;a.asset_id=new_uuid();a.name="Budget synthetic character";a.source_sha256=std::string(64,'a');a.mesh.joints.emplace_back();for(const auto p:{Vec3{0,0,0},Vec3{1,0,0},Vec3{.5f,1.8f,0}}){CharacterVertex v;v.position=p;v.normal={0,0,-1};v.u=p.x;v.v=p.y/1.8f;a.mesh.vertices.push_back(v);}a.mesh.indices={0,1,2};a.images={{ImageSemantic::srgb_color,{{1,1,{240,50,200,255}}}}};a.materials={{0,{1,1,1},.2f,true}};a.draws={{0,3,0}};validate_character_asset(a);return a;}
std::vector<unsigned char> read(const std::filesystem::path& path){std::ifstream f(path,std::ios::binary);std::vector<unsigned char> bytes{std::istreambuf_iterator<char>(f),{}};need(bytes.size()==54+256*256*4,"GPU capture invalid size");return bytes;}
std::vector<unsigned char> capture(Dx12Renderer& r,NativeWindow& w,const Camera& camera,const CharacterInstance* instance,const std::filesystem::path& path){need(w.poll(),"Window closed during budget proof");if(instance)r.render(camera,{},*instance);else r.render(camera);r.capture(path);return read(path);}
bool same_counters(const RenderStats& a,const RenderStats& b){return a.frames==b.frames&&a.scene_replacements==b.scene_replacements&&a.full_idle_calls==b.full_idle_calls&&a.transient_buffer_allocations==b.transient_buffer_allocations&&a.character_replacements==b.character_replacements&&a.character_buffer_allocations==b.character_buffer_allocations&&a.character_texture_allocations==b.character_texture_allocations&&a.character_replacement_peak_gpu_bytes==b.character_replacement_peak_gpu_bytes&&a.scene_active_gpu_bytes==b.scene_active_gpu_bytes&&a.character_active_gpu_bytes==b.character_active_gpu_bytes;}
template<class F>void rejected(F operation,Dx12Renderer& renderer,const char* why){const auto before=renderer.stats();bool refused=false;try{operation();}catch(const std::invalid_argument&){refused=true;}need(refused,why);need(same_counters(before,renderer.stats()),"Budget rejection changed active resources/counters or idled GPU");}
}
int main(int argc,char** argv){try{
 need(argc==3,"Pass installed shaders and owned evidence directory");const std::filesystem::path output=argv[2];std::filesystem::create_directories(output);NativeWindow window(256,256,L"AI-BS whole-content GPU budget proof",false);Dx12Renderer renderer(window,base(),argv[1]);Camera camera;camera.position={2.2f,1.2f,-3.7f};camera.yaw=std::atan2(-2.2f,3.7f);camera.pitch=-.0696f;
 const auto layer=textured();const auto light=lighting();const auto actor=character();CharacterInstance instance;instance.pose=character_bind_pose(actor.mesh);const auto unlimited=std::numeric_limits<std::uint64_t>::max();
 renderer.set_scene_character_asset(base(),{},SceneLighting{},nullptr);const auto baseline_bytes=renderer.stats().scene_active_gpu_bytes;need(baseline_bytes>0,"Retained fixed content resources were not counted");const auto baseline=capture(renderer,window,camera,nullptr,output/"baseline.bmp");
 // Calibrate exact committed allocation on this adapter, not guessed mip bytes.
 renderer.set_scene_character_asset(base(true),layer,light,&actor);const auto full_bytes=renderer.stats().scene_active_gpu_bytes;need(full_bytes>baseline_bytes,"Texture/shadow/character resources were not counted");const auto expected=capture(renderer,window,camera,&instance,output/"calibrated-full.bmp");need(expected!=baseline,"Candidate scene must visibly differ for rejection proof");
 renderer.set_scene_character_asset(base(),{},SceneLighting{},nullptr);const auto original=capture(renderer,window,camera,nullptr,output/"before-rejection.bmp");need(original==baseline,"Calibration reset did not restore original pixels");
 rejected([&]{renderer.set_scene_character_asset_bounded(base(true),layer,light,&actor,full_bytes-1);},renderer,"One byte below actual whole-scene allocation was accepted");renderer.capture(output/"rejected.bmp");need(read(output/"rejected.bmp")==original,"Rejected scene changed latest completed GPU pixels");
 renderer.set_scene_character_asset_bounded(base(true),layer,light,&actor,full_bytes);need(renderer.stats().scene_active_gpu_bytes==full_bytes,"Exact whole-scene allocation threshold rejected/miscounted");need(capture(renderer,window,camera,&instance,output/"exact-full.bmp")==expected,"Exact-budget scene differs from calibrated GPU pixels");
 const auto char_replacements=renderer.stats().character_replacements;renderer.set_scene_bounded(base(),{},SceneLighting{},unlimited);const auto with_character=renderer.stats().scene_active_gpu_bytes;need(with_character>baseline_bytes&&with_character<full_bytes,"Preserved character or removed shadow/texture allocation count incorrect");need(renderer.stats().character_replacements==char_replacements,"Three-layer transaction replaced character");const auto preserved=capture(renderer,window,camera,&instance,output/"character-preserved.bmp");
 rejected([&]{renderer.set_scene_bounded(base(true),layer,light,full_bytes-1);},renderer,"Preserved-character bytes omitted from three-layer budget");renderer.capture(output/"preserved-rejected.bmp");need(read(output/"preserved-rejected.bmp")==preserved,"Preserved-character rejection changed actual GPU image");renderer.set_scene_bounded(base(true),layer,light,full_bytes);need(renderer.stats().scene_active_gpu_bytes==full_bytes&&renderer.stats().character_replacements==char_replacements,"Exact three-layer budget lost/replaced character");
 renderer.set_scene_character_asset_bounded(base(),{},SceneLighting{},nullptr,baseline_bytes);need(renderer.stats().scene_active_gpu_bytes==baseline_bytes&&renderer.stats().character_active_gpu_bytes==0,"Removing character/textures/shadow did not return exact active baseline");need(capture(renderer,window,camera,nullptr,output/"cleared.bmp")==baseline,"Clearing whole content changed retained base pixels");
 rejected([&]{renderer.set_scene_bounded({},TexturedScene{},SceneLighting{},0);},renderer,"Zero budget ignored retained fixed transient/lighting buffers");
 // Preserve the existing vertex-colored CharacterMesh shader path, including
 // its separately owned white fallback image, through one bounded transaction.
 renderer.set_scene(base(true),layer,light,&actor.mesh);const auto legacy_bytes=renderer.stats().scene_active_gpu_bytes;
 need(legacy_bytes>baseline_bytes&&legacy_bytes<full_bytes,"Legacy character exact allocation must include its owned white image only");
 const auto legacy_pixels=capture(renderer,window,camera,&instance,output/"legacy-calibrated.bmp");
 renderer.set_scene_character_asset_bounded(base(),{},SceneLighting{},nullptr,baseline_bytes);const auto legacy_before=capture(renderer,window,camera,nullptr,output/"legacy-before.bmp");
 rejected([&]{renderer.set_scene_character_bounded(base(true),layer,light,&actor.mesh,legacy_bytes-1);},renderer,"Legacy fallback bypassed one-byte-below joint GPU admission");renderer.capture(output/"legacy-rejected.bmp");need(read(output/"legacy-rejected.bmp")==legacy_before,"Rejected legacy fallback changed current pixels");
 renderer.set_scene_character_bounded(base(true),layer,light,&actor.mesh,legacy_bytes);need(renderer.stats().scene_active_gpu_bytes==legacy_bytes,"Exact legacy fallback allocation threshold failed");need(capture(renderer,window,camera,&instance,output/"legacy-exact.bmp")==legacy_pixels,"Bounded legacy fallback changed vertex-colored shader behavior");
 // A composed CPU vector can retain far more capacity than its current vertex
 // count. Subtract it before fallback admission at the joint128MiB boundary.
 auto composed=base(true);composed.vertices.reserve(900000);const auto composed_cpu=memory_scene_mesh_bytes(composed);need(composed_cpu>32u*1024u*1024u,"Large CPU projection fixture must exceed generic control reserve");
 const auto other_cpu=memory_content_resident_limit-composed_cpu-static_cast<std::size_t>(legacy_bytes);
 renderer.set_scene_character_bounded(base(),{},SceneLighting{},nullptr,baseline_bytes);const auto combined_before=capture(renderer,window,camera,nullptr,output/"combined-before.bmp");
 rejected([&]{renderer.set_scene_character_bounded(composed,layer,light,&actor.mesh,memory_scene_gpu_remainder(other_cpu+1,composed));},renderer,"Near128MiB composed CPU plus fallback GPU overrun accepted");renderer.capture(output/"combined-rejected.bmp");need(read(output/"combined-rejected.bmp")==combined_before,"Combined CPU/GPU budget rejection changed scene pixels");
 renderer.set_scene_character_bounded(composed,layer,light,&actor.mesh,memory_scene_gpu_remainder(other_cpu,composed));need(renderer.stats().scene_active_gpu_bytes==legacy_bytes,"Exact combined CPU/GPU threshold failed");need(capture(renderer,window,camera,&instance,output/"combined-exact.bmp")==legacy_pixels,"Reserved CPU capacity changed rendered geometry");
 composed={};need(memory_scene_mesh_bytes(composed)==0,"Released composed CPU source retained allocation");renderer.set_scene_character_bounded(base(),{},SceneLighting{},nullptr,baseline_bytes);need(renderer.stats().scene_active_gpu_bytes==baseline_bytes,"Clearing legacy fallback retained GPU allocation");
 for(unsigned cycle=0;cycle<3;++cycle){renderer.set_scene_character_asset_bounded(base(true),layer,light,&actor,full_bytes);need(renderer.stats().scene_active_gpu_bytes==full_bytes,"Repeated candidate allocations accumulated active content bytes");renderer.set_scene_character_asset_bounded(base(),{},SceneLighting{},nullptr,baseline_bytes);need(renderer.stats().scene_active_gpu_bytes==baseline_bytes,"Repeated clear did not release active content resources");}
 renderer.wait_idle();const auto final=renderer.stats();need(final.debug_layer&&final.debug_errors==0&&final.debug_warnings==0,"Budget proof DX12 debug diagnostics");std::ofstream report(output/"verification.json");report<<"{\"status\":\"passed\",\"checks\":"<<checks<<",\"baseline_active_gpu_bytes\":"<<baseline_bytes<<",\"full_active_gpu_bytes\":"<<full_bytes<<",\"legacy_character_active_gpu_bytes\":"<<legacy_bytes<<",\"composed_cpu_bytes\":"<<composed_cpu<<",\"preserved_character_active_gpu_bytes\":"<<with_character<<",\"reject_bound\":"<<full_bytes-1<<",\"exact_threshold_passed\":true,\"rejected_counters_and_pixels_unchanged\":true,\"cycles\":3,\"active_bytes_return_to_baseline\":true,\"debug_errors\":"<<final.debug_errors<<",\"debug_warnings\":"<<final.debug_warnings<<",\"scope\":\"active committed chapter resources; excludes swapchain/depth/descriptors/driver and temporary upload peak\"}\n";need(report.good(),"Cannot write budget evidence");std::cout<<"PASS "<<checks<<" actual whole-content GPU publication budget checks\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
